+/** Passive diagnostics in the isolated Stirling checkout only. No gate reads these counters. */
+class StirlingWorkProbe(
+    private val key: MethodKey,
+    private val run: Int,
+    private val mode: ApMode,
+    private val language: LanguageManager,
+    private val manager: ApManager,
+) {
+    private var removedUnchanged = false
+    private var processed = 0L
+    private var changed = 0L
+    private var unchanged = 0L
+    private val processedKinds = LongArray(3)
+    private val processedPremises = LongArray(3)
+    private val processedBases = LongArray(2)
+    private val offers = LongArray(3)
+    private val accepted = LongArray(3)
+    private val rejected = LongArray(3)
+    private val offerBases = LongArray(2)
+    private var freshZero = 0L
+    private var freshFlow = 0L
+    private var freshTaint = 0L
+    private var workCalls = 0L
+    private var quantumYields = 0L
+    private var phaseYields = 0L
+    private var workComplete = 0L
+    private var clearCalls = 0L
+    private var nonemptyClears = 0L
+    private var clearsWithChanged = 0L
+    private var maxSeenAtClear = 0
+    private var epoch = 0L
+    private val rootSizes = LongArray(64)
+    private val maskSizes = LongArray(64)
+    private var maxRoot = 0L
+    private var maxMask = 0L
+    private var protectedPackets = 0L
+    private var lastItem: EdgeDelta? = null
+    private var largestItem: EdgeDelta? = null
+    private var nextLog = System.nanoTime() + LOG_NANOS
+    private var finalLogged = false
+
+    private data class ExactKey(val node: CommonInst, val premise: PremiseKey, val facts: Facts, val mask: TaintNode?)
+    private class Visit(var offeredEpoch: Long, var processedEpoch: Long = -1)
+    private val recent = object : LinkedHashMap<ExactKey, Visit>(257, 0.75f, true) {
+        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<ExactKey, Visit>?): Boolean = size > 256
+    }
+    private var witnessOffers = 0L
+    private var witnessLargeCheckSkips = 0L
+    private var acceptedAcrossEpoch = 0L
+    private var processedAcrossEpoch = 0L
+    private var witnessSample: String? = null
+
+    fun removed(wasUnchanged: Boolean) { removedUnchanged = wasUnchanged }
+    fun freshInitial(initial: InitialAp) {
+        when { initial.isZero -> freshZero++; initial.isFlow -> freshFlow++; else -> freshTaint++ }
+    }
+    fun workStarted() { workCalls++ }
+    fun workReturned(reason: Int) {
+        when (reason) { 0 -> workComplete++; 1 -> quantumYields++; 2 -> phaseYields++ }
+    }
+    fun cleared(seenSize: Int, changedPending: Boolean) {
+        clearCalls++; epoch++
+        if (seenSize != 0) {
+            nonemptyClears++
+            if (changedPending) clearsWithChanged++
