+        }
+    }
+    private fun premiseKind(premise: PremiseKey): Int = when {
+        premise.isZero -> 0; premise.isFlow -> 1; else -> 2
+    }
+    private fun factsKind(facts: Facts): Int = when (facts) { is Reach -> 0; is FlowTree -> 1; is TaintTree -> 2 }
+    private fun bucket(size: Long): Int = 63 - java.lang.Long.numberOfLeadingZeros(size.coerceAtLeast(1))
+    private fun witnessKey(delta: EdgeDelta): ExactKey? {
