+        val rootSize = when (val f = delta.facts) { is FlowTree -> f.root.size; is TaintTree -> f.root.size; is Reach -> 1L }
+        val maskSize = (delta.facts as? TaintTree)?.nonSubsumable?.size ?: 0L
+        if (rootSize > 1024 || maskSize > 1024) { witnessLargeCheckSkips++; return null }
+        if ((delta.node.hashCode() and 63) != 0) return null
+        return ExactKey(delta.node, delta.premise, delta.facts, (delta.facts as? TaintTree)?.nonSubsumable)
+    }
+    fun unchangedOffer(delta: EdgeDelta, fresh: Boolean) {
+        val kind = premiseKind(delta.premise)
+        offers[kind]++
+        if (fresh) accepted[kind]++ else rejected[kind]++
+        offerBases[if (delta.facts.base == STATIC) 0 else 1]++
+        val selected = witnessKey(delta) ?: return
+        witnessOffers++
+        val previous = recent[selected]
+        if (fresh && previous != null && previous.processedEpoch >= 0 && previous.processedEpoch != epoch) {
+            acceptedAcrossEpoch++
+            if (witnessSample == null) witnessSample = "oldEpoch=${previous.processedEpoch} newEpoch=$epoch ${describe(delta)}"
+        }
+        if (previous == null) recent[selected] = Visit(epoch)
