+    fun processing(delta: EdgeDelta) {
+        processed++
+        if (removedUnchanged) unchanged++ else changed++
+        processedKinds[factsKind(delta.facts)]++
+        processedPremises[premiseKind(delta.premise)]++
+        processedBases[if (delta.facts.base == STATIC) 0 else 1]++
+        lastItem = delta
+        val root = when (val f = delta.facts) { is FlowTree -> f.root; is TaintTree -> f.root; is Reach -> null }
+        if (root != null) {
+            rootSizes[bucket(root.size)]++
+            if (root.size > maxRoot) { maxRoot = root.size; largestItem = delta }
+        }
+        (delta.facts as? TaintTree)?.nonSubsumable?.let {
+            protectedPackets++; maskSizes[bucket(it.size)]++; maxMask = maxOf(maxMask, it.size)
+        }
+        if (removedUnchanged) witnessKey(delta)?.let { selected ->
+            val previous = recent[selected]
+            if (previous != null) {
+                if (previous.processedEpoch >= 0 && previous.processedEpoch != epoch) processedAcrossEpoch++
+                previous.processedEpoch = epoch
+            }
+        }
+    }
