+                "freshZero=$freshZero freshFlow=$freshFlow freshTaint=$freshTaint edgeDeltas=$edgeDeltas recordCrossings=$crossings " +
+                "processedKind_REACH_FLOW_TAINT=${processedKinds.contentToString()} processedPremise_ZERO_FLOW_TAINT=${processedPremises.contentToString()} " +
+                "processedBase_STATIC_OTHER=${processedBases.contentToString()} unchangedOffers=${offers.contentToString()} " +
+                "unchangedAccepted=${accepted.contentToString()} unchangedRejected=${rejected.contentToString()} unchangedOfferBase_STATIC_OTHER=${offerBases.contentToString()} " +
+                "workCalls=$workCalls quantumYields=$quantumYields phaseYields=$phaseYields workComplete=$workComplete " +
+                "clearCalls=$clearCalls nonemptyClears=$nonemptyClears clearsWithChanged=$clearsWithChanged maxSeenAtClear=$maxSeenAtClear epoch=$epoch " +
+                "treeSizeLog2=${histogram(rootSizes)} maxTreeNodeOccurrences=$maxRoot maskSizeLog2=${histogram(maskSizes)} maxMaskNodeOccurrences=$maxMask protectedPackets=$protectedPackets " +
+                "witnessDomain=steps_ge_1M_nodeHash_low6_zero_rootAndMask_le_1024_LRU256 witnessLargeCheckSkips=$witnessLargeCheckSkips sampledWitnessOffers=$witnessOffers exactAcceptedAcrossEpoch=$acceptedAcrossEpoch exactProcessedAcrossEpoch=$processedAcrossEpoch " +
+                "witness=${quoted(witnessSample ?: "none")} queue=${quoted(queue)} " +
+                "last=${quoted(lastItem?.let(::describe) ?: "none")} largest=${quoted(largestItem?.let(::describe) ?: "none")}"
+        }
+    }
+    private fun marks(set: MarkSet): String = (0 until minOf(3, set.size)).joinToString(prefix = "[", postfix = "]") {
+        val mark = TaintMark(set.data[it]); "${mark.id}:${manager.marks.name(mark).take(240)}"
+    } + if (set.size > 3) "+${set.size - 3}" else ""
+    private class Frame(val node: TrieNode<*>, val path: IntArray, var next: Int = -1)
+    /** At most 64 trie-node visits and three nonempty path leaves; no eager leaf API. */
+    private fun sample(root: TrieNode<*>): String {
+        val stack = ArrayDeque<Frame>(); stack.addLast(Frame(root, IntArray(0)))
+        val result = ArrayList<String>(3); var visits = 0
+        while (stack.isNotEmpty() && visits < 64 && result.size < 3) {
+            val frame = stack.peekLast()
+            if (frame.next < 0) {
+                visits++; frame.next = 0
+                if (!frame.node.leaf.isEmpty) {
+                    val path = frame.path.joinToString(".") { manager.accessors.accessor(it).toString().take(100) }
+                    val leaf = frame.node.leaf
+                    result += "$path:" + if (leaf is TaintLeaves) "exact=${marks(leaf.exact)} any=${marks(leaf.any)}" else "FLOW"
+                }
+            }
+            val children = frame.node.childData
+            if (children == null || frame.next == children.size) stack.removeLast()
+            else {
+                val index = frame.next++
+                stack.addLast(Frame(children[index], frame.path + frame.node.accessorData!![index]))
+            }
+        }
+        return "visits=$visits leaves=${result.joinToString(";")} truncated=${stack.isNotEmpty()}"
+    }
+    private fun describe(delta: EdgeDelta): String {
+        val premise = delta.premise
+        val initial = (0 until minOf(3, premise.size)).joinToString(";") {
+            val member = premise.member(it)
+            "id=${member.id} base=${member.base} path=${member.pathArray.contentToString()} tail=${member.tail} mark=${member.mark} E=${member.exclusion}"
+        }
+        val facts = delta.facts
+        val shape = when (facts) {
+            is Reach -> "REACH"
+            is FlowTree -> "FLOW tail=${facts.tail} E=${facts.exclusion} mx=${facts.markExclusion} ${sample(facts.root)}"
+            is TaintTree -> "TAINT tail=${facts.anyTail} E=${facts.exclusion} ${sample(facts.root)} mask=" +
+                (facts.nonSubsumable?.let(::sample) ?: "none")
+        }
+        return "node=${language.getInstIndex(delta.node)} premiseSize=${premise.size} initial=[$initial] base=${facts.base} layer=${facts.layer} $shape".take(6000)
+    }
+    companion object : KLogging() { private const val LOG_NANOS = 10_000_000_000L }
+}
